={{ JSON.stringify({
  phoneNumberId: $env.VAPI_PHONE_NUMBER_ID,
  phoneCallProviderBypassEnabled: true,
  customer: { number: $json.callerNumber },
  assistant: {
    name: $json.assistantName,
    firstMessage: $json.firstMessage,
    firstMessageMode: 'assistant-speaks-first',
    model: {
      provider: 'openai',
      model: 'gpt-4o-mini',
      temperature: 0.4,
      messages: [ { role: 'system', content: $json.systemPrompt } ],
      tools: [
        {
          type: 'function',
          async: true,
          messages: [ { type: 'request-start', content: $json.transferMessage, blocking: true } ],
          function: {
            name: 'transfer_to_human',
            description: 'Warm-transfer the live call to a human agent. Call this when the caller asks for a person or an escalation rule is met.',
            strict: true,
            parameters: {
              type: 'object',
              properties: {
                reason: { type: 'string', description: 'One sentence summarising why the caller needs a human, read aloud to the agent before the call connects.' },
                department: { type: 'string', enum: [ 'support', 'sales' ], description: 'Which human team should take the call.' }
              },
              required: [ 'reason', 'department' ]
            }
          },
          server: Object.assign(
            {
              url: ($env.WEBHOOK_URL || (($('Twilio DTMF Receiver').first().json.headers['x-forwarded-proto'] || 'https').split(',')[0] + '://' + $('Twilio DTMF Receiver').first().json.headers.host)).replace(/\/+$/, '')
                + '/webhook/vapi-escalation?callSid=' + encodeURIComponent($json.callSid)
                + '&accountSid=' + encodeURIComponent($json.accountSid)
                + '&department=' + $json.department,
              timeoutSeconds: 20
            },
            $env.VAPI_TOOL_SECRET ? { headers: { 'x-vapi-secret': $env.VAPI_TOOL_SECRET } } : {}
          )
        }
      ]
    },
    voice: { provider: '11labs', voiceId: $json.voiceId, model: 'eleven_flash_v2_5' },
    transcriber: { provider: 'deepgram', model: 'nova-3', language: 'en' },
    stopSpeakingPlan: { numWords: 0, voiceSeconds: 0.2, backoffSeconds: 1 },
    maxDurationSeconds: 900,
    metadata: { department: $json.department, twilioCallSid: $json.callSid, source: 'n8n-ai-voice-agent-template' }
  }
}) }}

