// Normalises the Vapi "tool-calls" webhook into everything the transfer needs.
// Vapi docs: https://docs.vapi.ai/tools/custom-tools
const req = $input.first().json;
const body = req.body || {};
const message = body.message || {};
const headers = req.headers || {};
const query = req.query || {};

// Optional shared secret (set VAPI_TOOL_SECRET to enable it).
const expectedSecret = $env.VAPI_TOOL_SECRET || '';
const authorized = !expectedSecret || headers['x-vapi-secret'] === expectedSecret;

const toolCalls = Array.isArray(message.toolCallList) ? message.toolCallList : [];
const toolCall = toolCalls.find((tc) => (tc.function?.name || tc.name) === 'transfer_to_human') || toolCalls[0] || {};
let args = toolCall.function?.arguments ?? toolCall.arguments ?? {};
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch (e) { args = {}; }
}

const metadata = message.assistant?.metadata || message.call?.assistant?.metadata || {};
const requested = String(args.department || query.department || metadata.department || 'support').toLowerCase();
const department = requested === 'sales' ? 'sales' : 'support';
const reason = String(args.reason || 'Caller asked to speak with a person.').replace(/\s+/g, ' ').trim().slice(0, 300);
const callSid = String(query.callSid || metadata.twilioCallSid || message.call?.phoneCallProviderId || '');
const accountSid = String(query.accountSid || $env.TWILIO_ACCOUNT_SID || '');
const transferNumber = String((department === 'sales' ? $env.HUMAN_SALES_NUMBER : $env.HUMAN_SUPPORT_NUMBER) || '').trim();

let errorReason = '';
if (!authorized) errorReason = 'Unauthorized tool call.';
else if (!toolCall.id) errorReason = 'No tool call found in the request.';
else if (!/^CA[0-9a-fA-F]{32}$/.test(callSid)) errorReason = 'Missing or invalid Twilio Call SID.';
else if (!/^AC[0-9a-fA-F]{32}$/.test(accountSid)) errorReason = 'Missing or invalid Twilio Account SID.';
else if (!/^\+[1-9]\d{6,14}$/.test(transferNumber)) errorReason = 'No valid E.164 transfer number configured for ' + department + '.';

// Twilio fetches this URL when the human answers and plays the briefing to them only.
const proto = String(headers['x-forwarded-proto'] || 'https').split(',')[0].trim();
const baseUrl = String($env.WEBHOOK_URL || (proto + '://' + headers.host)).replace(/\/+$/, '');
const whisperUrl = baseUrl + '/webhook/transfer-whisper?department=' + department + '&reason=' + encodeURIComponent(reason);

const xml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const voice = 'Polly.Joanna-Neural';
const transferTwiml = '<?xml version="1.0" encoding="UTF-8"?>'
  + '<Response>'
  + '<Dial timeout="25">'
  + '<Number url="' + xml(whisperUrl) + '" method="POST">' + xml(transferNumber) + '</Number>'
  + '</Dial>'
  + '<Say voice="' + voice + '">Sorry, nobody from our ' + department + ' team is available right now. Please try again later. Goodbye.</Say>'
  + '</Response>';

return [{
  json: {
    valid: !errorReason,
    authorized,
    errorReason,
    toolCallId: toolCall.id || '',
    department,
    reason,
    callSid,
    accountSid,
    transferNumber,
    transferTwiml,
  },
}];
